from pathlib import Path
from collections import Counter
import json,sys,hashlib
ROOT=Path(__file__).resolve().parent;OLD=ROOT.parent/'coordinate-yolo-selftrain-20261015';V3=ROOT.parent/'coordinate-finetune-20261015/paired-v3'
sys.path.insert(0,str(OLD));from coordinate_decode import iou
read=lambda p:json.loads(p.read_text(encoding='utf-8-sig'))
pred=read(ROOT/'evaluation.json');manifest=read(ROOT/'manifest.json')
fit={r['id']:r for r in manifest['rows'] if r['kind']=='annotated-text'}
dev={r['id']:r for r in read(V3/'development-corpus.json')['frames']}
truth={r['id']:r for r in read(ROOT.parent/'coordinate-label-expansion-20261015/expanded-corpus-v5.json')['frames']}
truth.update(dev);scenes={r['id']:r['sceneGroup'] for r in read(V3/'paired-manifest.json')['rows']}
assert not set(fit)&set(dev);groups={};judgments=[];wrong=[];gt=Counter();matched=Counter();reasons=Counter()
for row in pred['results']:
    fid=row['id'];f=truth[fid];s=row['decode']['selected'];xyz=s['xyz'] if s else None
    if f['state']=='present':outcome='miss' if xyz is None else 'correct' if xyz==[f['expected'][k] for k in 'xyz'] else 'wrong'
    elif f['state']=='absent':outcome='trueNegative' if xyz is None else 'falsePositive'
    else:outcome='unknownNoReturn' if xyz is None else 'unknownReturned'
    memberships=['trained-fit-only'] if fid in fit else ['all-development']
    if fid in dev and fid in scenes:memberships.append(scenes[fid])
    if fid in dev and 776<=int(fid[-6:])<=787:memberships.append('heldout-stationary-776-787')
    for group in memberships:
        c=groups.setdefault(group,Counter());c['frames']+=1;c[outcome]+=1
    judgment={'id':fid,'trainedFitOnly':fid in fit,'state':f['state'],'expected':f['expected'],'outcome':outcome,'decoded':row['decode']};judgments.append(judgment)
    if outcome in ['wrong','falsePositive']:wrong.append(judgment)
    if fid in dev and f['state']=='present' and outcome=='miss':reasons[row['decode']['reason']]+=1
    if fid in fit:
        used=set()
        for obj in fit[fid]['objects']:
            gt[obj['char']]+=1
            candidates=[(iou(obj['xyxy'],d['xyxy']),i) for i,d in enumerate(row['detections']) if i not in used and d['char']==obj['char']]
            if candidates:
                overlap,index=max(candidates)
                if overlap>=.5:used.add(index);matched[obj['char']]+=1
summary=[{'group':g,**{k:c[k] for k in ['frames','correct','wrong','miss','falsePositive','trueNegative','unknownReturned','unknownNoReturn']}} for g,c in groups.items()]
assert next(r for r in summary if r['group']=='all-development')['frames']==319
report={'scope':'67 training text frames at 42 XYZ. Frozen same-session170 present,141 absent,8 unknown development frames, not independent acceptance.',
 'summary':summary,'wrongCases':wrong,'judgments':judgments,'developmentMissReasons':dict(reasons),
 'fitCharactersAtIoU50AndConf25':{c:{'groundTruth':gt[c],'matched':matched[c]} for c in manifest['classes']},
 'thirdPartyGameWeightsOrPseudoLabelsUsed':False,'productionChanged':False,'candidateAccepted':False}
out=ROOT/'report.json';assert not out.exists();out.write_text(json.dumps(report,ensure_ascii=False,indent=2))
for r in summary:print(r)
print('Development miss reasons',dict(reasons))
